// Bundles the toolkit's workflows/ scripts and the project initializer into
// resources/ so the extension is self-contained once packaged: a .vsix only
// includes files under the extension root, and resources/ is the only place
// the runtime looks for them (see toolkitRunner.ts).
//
// Both sources live in this repository, one level up from scripts/. They are
// build inputs rather than checked-in output, so resources/workflows,
// resources/codicons, and resources/nova-expo stay gitignored and are
// regenerated by every compile, watch, and package run.
const fs = require('node:fs');
const path = require('node:path');

const sourceDir = path.resolve(__dirname, '..', 'workflows');
const targetDir = path.resolve(__dirname, '..', 'resources', 'workflows');

function copyRecursive(source, target) {
  const stat = fs.statSync(source);
  if (stat.isDirectory()) {
    fs.mkdirSync(target, { recursive: true });
    for (const entry of fs.readdirSync(source)) {
      if (entry === 'node_modules' || entry === 'test') continue;
      copyRecursive(path.join(source, entry), path.join(target, entry));
    }
    return;
  }
  fs.copyFileSync(source, target);
  if (source.endsWith('.sh')) {
    fs.chmodSync(target, 0o755);
  }
}

if (!fs.existsSync(sourceDir)) {
  throw new Error(`Toolkit workflows directory not found: ${sourceDir}`);
}

fs.rmSync(targetDir, { recursive: true, force: true });
copyRecursive(sourceDir, targetDir);
process.stdout.write(`copied ${sourceDir} -> ${targetDir}\n`);

const codiconsSource = path.resolve(__dirname, '..', 'node_modules', '@vscode', 'codicons', 'dist');
const codiconsTarget = path.resolve(__dirname, '..', 'resources', 'codicons');
fs.rmSync(codiconsTarget, { recursive: true, force: true });
fs.mkdirSync(codiconsTarget, { recursive: true });
for (const file of ['codicon.css', 'codicon.ttf']) {
  fs.copyFileSync(path.join(codiconsSource, file), path.join(codiconsTarget, file));
}
process.stdout.write(`copied codicon assets -> ${codiconsTarget}\n`);

const initializerSource = path.resolve(__dirname, '..', 'nova-expo');
const initializerTarget = path.resolve(__dirname, '..', 'resources', 'nova-expo');
if (!fs.existsSync(initializerSource)) {
  throw new Error(`Nova Expo initializer not found: ${initializerSource}`);
}
fs.rmSync(initializerTarget, { recursive: true, force: true });
copyRecursive(initializerSource, initializerTarget);
process.stdout.write(`copied ${initializerSource} -> ${initializerTarget}\n`);
